api_key = db.GetKey("HACK_MD5_APIKEY")
api_email = db.GetKey("HACK_MD5_EMAIL")

handle = func(hash /*string*/) {
    # handle your origin str
    url = sprintf("http://www.cmd5.com/api.ashx?email=%s&key=%s&hash=%s", api_email,api_key,hash)
    rsp,_,_=poc.Get(url, poc.https(false))
    body = rsp.GetBody()
    println(body)
    if body.Contains("CMD5-ERROR:0"){
        return "解密失败"
    } else if body.Contains("CMD5-ERROR:-1"){
        return "无效的用户名密码"
    }else if body.Contains("CMD5-ERROR:-2"){
        return "余额不足"
    }else if body.Contains("CMD5-ERROR:-3"){
        return "解密服务器故障"
    }else if body.Contains("CMD5-ERROR:-4"){
        return "不识别的密文"
    }else if body.Contains("CMD5-ERROR:-7"){
        return "不支持的类型"
    }else if body.Contains("CMD5-ERROR:-8"){
        return "api权限被禁止"
    }else if body.Contains("CMD5-ERROR:-9"){
        return "条数超过100条"
    }else if body.Contains("CMD5-ERROR:-999"){
        return "其它错误"
    } else {
        return body
    }

}
